import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] pos = new int[n + 1];
        for (int i = 0; i < n; i++) pos[nextInt()] = i;
        int left = n, right = -1;
        StringBuilder sb = new StringBuilder(n);
        for (int k = 1; k <= n; k++) {
            left = Math.min(left, pos[k]);
            right = Math.max(right, pos[k]);
            sb.append(right - left + 1 == k ? '1' : '0'); // 1..k fill the span exactly
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	pos := make([]int, n+1)
	for i := 0; i < n; i++ {
		pos[readInt()] = i
	}
	left, right := n, -1
	ans := make([]byte, n)
	for k := 1; k <= n; k++ {
		left = min(left, pos[k])
		right = max(right, pos[k])
		ans[k-1] = '0'
		if right-left+1 == k { // 1..k fill the span exactly
			ans[k-1] = '1'
		}
	}
	fmt.Println(string(ans))
}
